  async function arcGISSchools(where2, limit2) {
    const params = new URLSearchParams({ where: where2, outFields: "school_name,suburb,state,postcode", f: "json", resultRecordCount: String(limit2) });
    const resp = await fetch(`https://portal.data.nsw.gov.au/arcgis/rest/services/Hosted/ACARA_Schools_NSW/FeatureServer/0/query?${params}`, { signal: AbortSignal.timeout(6e3) });
    const data = await resp.json();
    return (data.features ?? []).map((f2) => ({
      name: f2.attributes.school_name,
      suburb: f2.attributes.suburb,
      state: f2.attributes.state ?? "NSW",
      postcode: String(f2.attributes.postcode ?? "")
    }));
  }
